{
 "quarter": "Q3 FY26",
 "callDate": "2026-01-30",
 "guidance": [
  {
   "metric": "revenue",
   "statement": "Growth in Q4 FY26 will be higher and the highest quarterly growth in FY26.",
   "quote": "One is, we believe that in the last quarter that is Q4, we will improve, our growth will be higher, it will be the highest quarterly growth in FY26.",
   "page": 10,
   "horizon": "Q4 FY26",
   "quantitative": true
  },
  {
   "metric": "profit",
   "statement": "Profitability will improve in Q4 compared to Q3 despite ongoing investments.",
   "quote": "And our profitability will improve from what we have in Q3 in spite of our investments.",
   "page": 10,
   "horizon": "Q4 FY26",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "The company will grow next year at a higher rate than the current year.",
   "quote": "We will for sure grow next year higher than this year. And we believe that we will be in a position to do it.",
   "page": 10,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "other",
   "statement": "A large part of the business may take 12 to 18 months to convert into solutions.",
   "quote": "We do believe that this may take 12 months to 18 months, for a large part of our business to convert into this",
   "page": 7,
   "horizon": "12-18 months",
   "quantitative": true
  },
  {
   "metric": "other",
   "statement": "Certain AI and specific solutions will start contributing in the next 3 to 4 months.",
   "quote": "specifically AI and some of the few solutions which we believe have potential would start in the next 3 months to 4 months.",
   "page": 7,
   "horizon": "3-4 months",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Margins will remain in the current ballpark next year and improve in the medium term.",
   "quote": "We will be in a position to be in the ballpark of the margins we have, little here and there, but similar margins in spite of the investment. But in the midterm, we are very sure that the margins will improve.",
   "page": 12,
   "horizon": "Medium term",
   "quantitative": false
  }
 ],
 "delivered": [
  {
   "metric": "revenue",
   "statement": "FY26 year-on-year growth was 9.4% in rupee terms and 3% in US Dollar terms.",
   "page": 4
  },
  {
   "metric": "revenue",
   "statement": "Constant currency growth in Quarter 3 was 1.5% with negative organic growth under 1%.",
   "page": 4
  },
  {
   "metric": "profit",
   "statement": "Net profit excluding the one-time Labor Code impact was INR 1.53 billion.",
   "page": 4
  },
  {
   "metric": "orders",
   "statement": "The TCV value of deals won during the quarter was INR 202 million.",
   "page": 4
  },
  {
   "metric": "other",
   "statement": "The fixed price revenue mix reached 66% compared to 59% last year.",
   "page": 4
  },
  {
   "metric": "other",
   "statement": "Cash at the end of the quarter stood at about INR 9 billion.",
   "page": 4
  }
 ],
 "tone": "Cautious on near-term macro and organic growth, but confident about strategic pivot to solutions, AI, and medium-term growth.",
 "pushback": [
  {
   "topic": "Solution cannibalization",
   "gist": "Analysts questioned whether the shift to solutions-led model would cannibalize existing revenue.",
   "page": 7
  },
  {
   "topic": "Guidance revision",
   "gist": "Analysts pressed on why earlier optimism on H2 has not fully reflected in Q3 margins and growth.",
   "page": 13
  },
  {
   "topic": "Japan/Asia slowdown",
   "gist": "Skepticism around declining revenues in Asia and the trajectory of large client programs in Japan.",
   "page": 18
  },
  {
   "topic": "AI solutions viability",
   "gist": "Questions raised on past failures of IT-approaches and what makes AI solutions adoptable now.",
   "page": 20
  }
]
}
